//! SMA-324 — end-to-end handoff: 3-agent finance triage, collisions, depth guard.

#[path = "common/mod.rs"]
mod common;

use common::{MockModel, MockTool};
use paigasus_helikon_core::{
    Agent, AgentEvent, AgentInput, FinishReason, LlmAgent, ModelEvent, RunConfig, RunContext,
    RunResultStreaming,
};

fn ctx() -> RunContext<()> {
    RunContext::ephemeral(())
}

fn transfer_turn(tool: &str) -> Vec<ModelEvent> {
    vec![
        ModelEvent::ToolCallDelta {
            call_id: "c1".to_owned(),
            name: Some(tool.to_owned()),
            args_delta: "{}".to_owned(),
        },
        ModelEvent::Finish {
            reason: FinishReason::ToolCalls,
        },
    ]
}

fn text_turn(text: &str) -> Vec<ModelEvent> {
    vec![
