            paigasus_helikon_core::PermissionDecision::Defer {
                prompt: "policy says wait".to_owned(),
            }
        } else {
            paigasus_helikon_core::PermissionDecision::Allow
        }
    }
}

/// A [`MockModel`] that records the requests it receives.
struct CapturingModel {
    inner: Arc<MockModel>,
    requests: Mutex<Vec<paigasus_helikon_core::ModelRequest>>,
}

#[async_trait]
impl paigasus_helikon_core::Model for CapturingModel {
    async fn invoke(
        &self,
        request: paigasus_helikon_core::ModelRequest,
        cancel: paigasus_helikon_core::CancellationToken,
    ) -> Result<
        futures_core::stream::BoxStream<
            'static,
            Result<ModelEvent, paigasus_helikon_core::ModelError>,
        >,
        paigasus_helikon_core::ModelError,
    > {
        self.requests.lock().unwrap().push(request.clone());
        self.inner.invoke(request, cancel).await
    }

    fn capabilities(&self) -> paigasus_helikon_core::ModelCapabilities {
        paigasus_helikon_core::ModelCapabilities::default()
    }
}

/// The text of the `ToolResult` items in `items`.
fn tool_result_texts(items: &[paigasus_helikon_core::Item]) -> Vec<String> {
    use paigasus_helikon_core::{ContentPart, Item};
    items
        .iter()
        .filter_map(|i| match i {
            Item::ToolResult { content, .. } => Some(
                content
                    .iter()
                    .filter_map(|p| match p {
                        ContentPart::Text { text } => Some(text.as_str()),
                        _ => None,
                    })
                    .collect::<String>(),
            ),
            _ => None,
        })
        .collect()
}

async fn drain(agent: &impl Agent<()>, ctx: RunContext<()>) -> Vec<AgentEvent> {
    use futures_util::StreamExt as _;
